import{_ as e,o as a,c as o,ah as r}from"./chunks/framework.BMM80GXQ.js";const s="/assets/2.0/images/dashboard/dashboard-overview.png",p=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/dashboard/index.md","filePath":"2.0/dashboard/index.md","lastUpdated":1775051911000}'),n={name:"2.0/dashboard/index.md"};function i(l,t,c,d,h,u){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The Dashboard is the first page you see after logging in to <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a>. It provides a complete overview of your product catalog, activity, and data quality at a glance, helping you quickly understand the state of your PIM and take action where needed.</p><p><img src="'+s+'" alt="Dashboard Overview"></p><h2 id="welcome-banner" tabindex="-1">Welcome Banner <a class="header-anchor" href="#welcome-banner" aria-label="Permalink to &quot;Welcome Banner&quot;">​</a></h2><p>At the top of the Dashboard, you will see a personalized greeting: <strong>&quot;Welcome back, [Your Name]&quot;</strong>. This section also provides quick action buttons so you can jump straight into common tasks:</p><ul><li><strong>Create Product</strong> - Takes you directly to the product creation page.</li><li><strong>Import Data</strong> - Opens the data import workflow.</li><li><strong>Export Data</strong> - Opens the data export workflow.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use these quick action buttons to save time instead of navigating through the sidebar menu.</p></div><h2 id="catalog-overview" tabindex="-1">Catalog Overview <a class="header-anchor" href="#catalog-overview" aria-label="Permalink to &quot;Catalog Overview&quot;">​</a></h2><p>Below the welcome banner, two summary cards display the total count of your core catalog entities:</p><ul><li><strong>Total Products</strong> - Shows the total number of products in your system. Click on this card to navigate directly to the Products listing page.</li><li><strong>Total Categories</strong> - Shows the total number of categories. Click on this card to navigate directly to the Categories listing page.</li></ul><h2 id="catalog-structure" tabindex="-1">Catalog Structure <a class="header-anchor" href="#catalog-structure" aria-label="Permalink to &quot;Catalog Structure&quot;">​</a></h2><p>This section gives you a quick snapshot of how your catalog is configured. It displays cards for each of the following:</p><ul><li><strong>Total Attributes</strong> - The number of product attributes defined in the system.</li><li><strong>Total Groups</strong> - The number of attribute groups.</li><li><strong>Total Families</strong> - The number of attribute families.</li><li><strong>Total Locales</strong> - The number of locales configured.</li><li><strong>Total Currencies</strong> - The number of currencies set up.</li><li><strong>Total Channels</strong> - The number of sales channels configured.</li></ul><p>These cards help you understand the breadth of your catalog setup without navigating to individual settings pages.</p><h2 id="needs-attention" tabindex="-1">Needs Attention <a class="header-anchor" href="#needs-attention" aria-label="Permalink to &quot;Needs Attention&quot;">​</a></h2><p>This section highlights items that require your immediate action. If there are <strong>unenriched products</strong> in your catalog (products that lack essential data), an alert will appear here prompting you to take action and improve your product data quality.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Unenriched products may not be ready for distribution to your sales channels. Review this section regularly to ensure your catalog is complete.</p></div><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><h3 id="product-statistics" tabindex="-1">Product Statistics <a class="header-anchor" href="#product-statistics" aria-label="Permalink to &quot;Product Statistics&quot;">​</a></h3><p>The Product Statistics panel provides a detailed numerical breakdown of your catalog:</p><ul><li><strong>Total Products</strong> - Overall product count.</li><li><strong>Active / Inactive</strong> - How many products are currently enabled vs. disabled.</li><li><strong>Product Type Distribution</strong> - Percentage split between configurable and simple product types.</li><li><strong>New This Week</strong> - Number of products created in the current week.</li><li><strong>With Variants</strong> - Number of products that have variant configurations.</li><li><strong>Avg Completeness</strong> - The average completeness score across all products.</li><li><strong>Enriched</strong> - Number of products considered fully enriched.</li></ul><h3 id="product-activity-last-7-days" tabindex="-1">Product Activity (Last 7 Days) <a class="header-anchor" href="#product-activity-last-7-days" aria-label="Permalink to &quot;Product Activity (Last 7 Days)&quot;">​</a></h3><p>This chart visualizes your team&#39;s recent work on the catalog. It plots the number of <strong>Created</strong> and <strong>Updated</strong> products per day over the last seven days, making it easy to spot trends in catalog activity.</p><h2 id="completeness" tabindex="-1">Completeness <a class="header-anchor" href="#completeness" aria-label="Permalink to &quot;Completeness&quot;">​</a></h2><p>The Completeness section shows how well your product data meets the requirements for each channel. Each channel is displayed with a <strong>percentage circle</strong> (e.g., 89%) indicating the overall completeness score.</p><p>You can also view locale-specific completeness within each channel. Helpful messages are displayed alongside each score:</p><ul><li><strong>&quot;Almost complete&quot;</strong> - Your data is nearly ready and only minor additions are needed.</li><li><strong>&quot;Low completeness, add details to improve&quot;</strong> - Significant product information is still missing.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Focus on channels and locales with lower completeness scores first to ensure your products are ready for distribution.</p></div><h2 id="channel-readiness" tabindex="-1">Channel Readiness <a class="header-anchor" href="#channel-readiness" aria-label="Permalink to &quot;Channel Readiness&quot;">​</a></h2><p>The Channel Readiness section shows a <strong>progress bar</strong> for each channel, indicating how many products are ready for that channel. For example, you might see <strong>&quot;2 of 3 products ready&quot;</strong> with a <strong>67%</strong> progress indicator.</p><p>This gives you a clear picture of which channels have complete product data and which ones still need attention.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><h3 id="recent-activity" tabindex="-1">Recent Activity <a class="header-anchor" href="#recent-activity" aria-label="Permalink to &quot;Recent Activity&quot;">​</a></h3><p>The Recent Activity feed displays a chronological list of actions performed in the system. Each entry includes:</p><ul><li><strong>Action type</strong> - Whether an entity was created, updated, or deleted.</li><li><strong>Entity type</strong> - The kind of entity affected (e.g., Family, Attribute, Product).</li><li><strong>User name</strong> - Who performed the action.</li><li><strong>Timestamp</strong> - When the action took place.</li></ul><p>This feed helps you track what changes have been made recently and by whom.</p><h3 id="data-transfer" tabindex="-1">Data Transfer <a class="header-anchor" href="#data-transfer" aria-label="Permalink to &quot;Data Transfer&quot;">​</a></h3><p>The Data Transfer panel shows the status of your import and export jobs. Each job displays its current status, which can be one of the following:</p><ul><li><strong>Completed</strong> - The job finished successfully.</li><li><strong>Processing</strong> - The job is currently running.</li><li><strong>Pending</strong> - The job is queued and waiting to start.</li><li><strong>Failed</strong> - The job encountered errors.</li><li><strong>Cancelled</strong> - The job was manually cancelled.</li></ul><p>Click on <strong>&quot;View All Jobs&quot;</strong> to navigate to the full Job Tracker page for more details.</p><h2 id="ai-agent" tabindex="-1">AI Agent <a class="header-anchor" href="#ai-agent" aria-label="Permalink to &quot;AI Agent&quot;">​</a></h2><p>At the bottom right corner of the Dashboard, you will find the <strong>&quot;Open Agenting PIM&quot;</strong> floating button. Clicking this button opens the AI Agent chat interface, which allows you to interact with UnoPim using natural language commands to manage your catalog, generate content, and perform various tasks.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The AI Agent can help you quickly create products, enrich content, and answer questions about your catalog without navigating through menus.</p></div>',43)])])}const m=e(n,[["render",i]]);export{p as __pageData,m as default};
